{
    Games myGame = null;
    Teams myTeam = null;
    Teams newActiveTeam = null;
    if (GameHelpers.IsValidTeam(myuser, _context, gameId, teamId, out myGame, out myTeam))
    {
        List<Player> Internalres = GameHelpers.BuildUpdatedGameState(myuser, _context, gameId, teamId, language);
        Player player = Internalres.Where(a => a.UserId == myuser.Userid).FirstOrDefault();
        ActionWithStates actionWithStates = player.actionWithStates.Where(a => a.action.Id == actionId).FirstOrDefault();
        if (actionWithStates != null && actionWithStates.status == "Ok")
        {
            foreach (StateRequirements stateRequirement in actionWithStates.statesRequirements)
            {
                myTeam.ActionNum++;
                StatesToActions newStateToAction = new StatesToActions();

                newStateToAction.ActionId = actionWithStates.action.Id.ToString();
                newStateToAction.CardId = actionWithStates.action.ParentId;
                newStateToAction.TeamId = teamId.ToString();
                newStateToAction.Regularity = stateRequirement.regularity;
                newStateToAction.MinValue = stateRequirement.minimalPoinst;
                newStateToAction.StateId = stateRequirement.id.ToString();
                newStateToAction.GameId = gameId.ToString();
                newStateToAction.Cost = stateRequirement.costPoinst;
                newStateToAction.Addition = stateRequirement.additionalPoinst;
                _context.StatesToActions.Add(newStateToAction);


                TeamHistoryMoves myMove = new TeamHistoryMoves();
                myMove.GameId = gameId.ToString();
                myMove.Teamid = teamId.ToString();
                myMove.Userid = myuser.Id.ToString();
                myMove.Points = stateRequirement.costPoinst + stateRequirement.additionalPoinst;
                myMove.Explanation = actionWithStates.action.Title;
                myMove.ActionId = actionWithStates.action.Id.ToString();
                myMove.StateId = stateRequirement.id.ToString();
                myMove.ActionNum = myTeam.ActionNum;
                myMove.CardId = actionWithStates.action.ParentId;
                _context.TeamHistoryMoves.Add(myMove);


            }
            _context.SaveChanges();

        }
    }
}

